import{_ as t,c as o,o as r,ah as a}from"./chunks/framework.DX1DJjtl.js";const u=JSON.parse('{"title":"TextBox","description":"","frontmatter":{},"headers":[],"relativePath":"api/elements/TextBox.md","filePath":"api/elements/TextBox.md","lastUpdated":1785055892000}'),d={name:"api/elements/TextBox.md"};function l(n,e,s,i,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="textbox" tabindex="-1">TextBox <a class="header-anchor" href="#textbox" aria-label="Permalink to &quot;TextBox&quot;">​</a></h1><p><em>extends Element</em></p><p>TextBox: multiline text editor with cursor, viewport scrolling, an optional vertical scrollbar and text selection. Fires &quot;change&quot;.</p><p>Selection: shift + arrows/home/end/pageUp/pageDown, or mouse dragging. Ctrl+A selects all, Ctrl+C copies, Ctrl+X cuts (Basalt-internal clipboard, shared between all TextBoxes; the system clipboard arrives via the normal CC paste event). Typing, enter, paste, backspace and delete replace or remove the selection first. Escape collapses it.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>text</td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Full buffer content joined with newlines (rawString: never reactive)</td></tr><tr><td>background</td><td><code>number|false</code></td><td><code>colors.black</code></td><td>Background color (false = transparent)</td></tr><tr><td>width</td><td><code>number</code></td><td><code>20</code></td><td>Width in terminal cells</td></tr><tr><td>height</td><td><code>number</code></td><td><code>8</code></td><td>Height in terminal cells</td></tr><tr><td>scrollbar</td><td><code>ItemViewScrollbarMode</code></td><td><code>&quot;auto&quot;</code></td><td>&quot;auto&quot;, &quot;always&quot; or &quot;hidden&quot;</td></tr><tr><td>scrollbarColor</td><td><code>number</code></td><td><code>colors.gray</code></td><td>Scrollbar track color</td></tr><tr><td>scrollbarThumbColor</td><td><code>number</code></td><td><code>colors.lightGray</code></td><td>Scrollbar thumb color</td></tr><tr><td>selectionBackground</td><td><code>number</code></td><td><code>colors.blue</code></td><td>text selection overlay</td></tr><tr><td>selectionForeground</td><td><code>number</code></td><td><code>colors.white</code></td><td>Text color of selected entries</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Registrar</th><th>Description</th></tr></thead><tbody><tr><td>change</td><td>:onChange(fn)</td><td>Fired after every edit with the full new text</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="textbox-getselection" tabindex="-1">TextBox:getSelection() <a class="header-anchor" href="#textbox-getselection" aria-label="Permalink to &quot;TextBox:getSelection()&quot;">​</a></h3><p>Returns the selected text (with newlines), or nil.</p><ul><li><strong>returns</strong> <strong>selection</strong> (<code>string?</code>) The selected text</li></ul><h3 id="textbox-deleteselection" tabindex="-1">TextBox:deleteSelection() <a class="header-anchor" href="#textbox-deleteselection" aria-label="Permalink to &quot;TextBox:deleteSelection()&quot;">​</a></h3><p>Removes the selected text.</p><ul><li><strong>returns</strong> <strong>deleted</strong> (<code>boolean</code>) True if there was a selection to remove</li></ul><h3 id="textbox-selectall" tabindex="-1">TextBox:selectAll() <a class="header-anchor" href="#textbox-selectall" aria-label="Permalink to &quot;TextBox:selectAll()&quot;">​</a></h3><p>Selects the whole buffer (what ctrl+a does).</p><ul><li><strong>returns</strong> (<code>self</code>)</li></ul><h3 id="textbox-copy" tabindex="-1">TextBox:copy() <a class="header-anchor" href="#textbox-copy" aria-label="Permalink to &quot;TextBox:copy()&quot;">​</a></h3><p>Copies the selection to the Basalt-internal clipboard (ctrl+c).</p><ul><li><strong>returns</strong> <strong>copied</strong> (<code>string?</code>) The copied text</li></ul><h3 id="textbox-cut" tabindex="-1">TextBox:cut() <a class="header-anchor" href="#textbox-cut" aria-label="Permalink to &quot;TextBox:cut()&quot;">​</a></h3><p>Cuts the selection into the Basalt-internal clipboard (ctrl+x).</p><ul><li><strong>returns</strong> <strong>cut</strong> (<code>string?</code>) The removed text</li></ul><h3 id="textbox-getclipboard" tabindex="-1">TextBox:getClipboard() <a class="header-anchor" href="#textbox-getclipboard" aria-label="Permalink to &quot;TextBox:getClipboard()&quot;">​</a></h3><p>Returns the Basalt-internal clipboard (shared between all TextBoxes).</p><ul><li><strong>returns</strong> <strong>clipboard</strong> (<code>string</code>) The clipboard content</li></ul><h3 id="textbox-setup" tabindex="-1">TextBox:setup() <a class="header-anchor" href="#textbox-setup" aria-label="Permalink to &quot;TextBox:setup()&quot;">​</a></h3><p>Initializes per-instance state and input handlers.</p><h3 id="textbox-handlemouse-event-btn-x-y" tabindex="-1">TextBox:handleMouse(event, btn, x, y) <a class="header-anchor" href="#textbox-handlemouse-event-btn-x-y" aria-label="Permalink to &quot;TextBox:handleMouse(event, btn, x, y)&quot;">​</a></h3><p>Routes mouse input in local coordinates (wheel scrolling etc.).</p><ul><li><p><strong>event</strong> (<code>string</code>) The mouse event name</p></li><li><p><strong>btn</strong> (<code>number</code>) Button or scroll direction</p></li><li><p><strong>x</strong> (<code>number</code>) Local x coordinate</p></li><li><p><strong>y</strong> (<code>number</code>) Local y coordinate</p></li><li><p><strong>returns</strong> <strong>consumer</strong> (<code>Element|nil</code>) The consuming element, or nil to pass through</p></li></ul><h3 id="textbox-handlekey-event-a-b" tabindex="-1">TextBox:handleKey(event, a, b) <a class="header-anchor" href="#textbox-handlekey-event-a-b" aria-label="Permalink to &quot;TextBox:handleKey(event, a, b)&quot;">​</a></h3><p>Handles keyboard input while focused.</p><ul><li><strong>event</strong> (<code>string</code>) The key event name (key, key_up, char, paste)</li><li><strong>a</strong> (<code>any</code>) Key code or typed text</li><li><strong>b</strong> (<code>any</code>, optional) Secondary key-event value</li></ul><h3 id="textbox-measure" tabindex="-1">TextBox:measure() <a class="header-anchor" href="#textbox-measure" aria-label="Permalink to &quot;TextBox:measure()&quot;">​</a></h3><p>Intrinsic size for basalt.auto().</p><ul><li><strong>returns</strong> <strong>width</strong> (<code>number</code>) The measured width</li><li><strong>returns</strong> <strong>height</strong> (<code>number</code>) The measured height</li></ul><h3 id="textbox-render-buf" tabindex="-1">TextBox:render(buf) <a class="header-anchor" href="#textbox-render-buf" aria-label="Permalink to &quot;TextBox:render(buf)&quot;">​</a></h3><p>Renders the element into the buffer.</p><ul><li><strong>buf</strong> (<code>Render</code>) The render buffer (local coordinates, pre-clipped)</li></ul>',41)])])}const b=t(d,[["render",l]]);export{u as __pageData,b as default};
